export function closestStation(lat, lon, stations) {
    if (!stations.length)
        return null;
    const radians = x => x * Math.PI / 180;
    let closest = null, best = Infinity;
    for (const s of stations) {
        const x = radians(s.lon - lon) * Math.cos(radians((lat + s.lat) / 2)), y = radians(s.lat - lat);
        const d = 6371 * Math.sqrt(x * x + y * y);
        if (d < best) {
            best = d;
            closest = s.name;
        }
    }
    return closest;
}
